/// <summary>§7.1–§7.10 全表白名单（强类型数据；类型即边界，来源注释承载数学语义）。</summary>
public static class GodotApiWhitelist
{
    // ── 作用域/资源/Claim 构造帮助器（保持编码紧凑、与 §7 表逐格对齐）──
