    [Fact]
    public void Analyzer_NoDiagnosticWhenReleased()
    {
        const string source = @"
public class Sample
{
    public void AddChild(object x) { }
    public void QueueFree() { }
    public void AcquireAndRelease()
    {
        AddChild(new object());
        QueueFree();
    }
}";
        var diags = RunAnalyzer(source).GetAwaiter().GetResult();
        Assert.DoesNotContain(diags, d => d.Id == "EAA0901");
    }

    // §8.3.1：acquire 但标 [EffectOverride]（逃逸通道）⇒ 不报 EAA0901（hasEscape 跳过）。
    [Fact]
    public void Analyzer_NoDiagnosticWhenOverrideAttr()
    {
        const string source = @"
using Cosmos.EffectAlgebra;
public class Sample
{
    public void AddChild(object x) { }
    [EffectOverride(""r"")]
    public void AcquireWithOverride()
    {
        AddChild(new object());
    }
}";
        var diags = RunAnalyzer(source).GetAwaiter().GetResult();
        Assert.DoesNotContain(diags, d => d.Id == "EAA0901");
    }
}
